var customerIds = new[] { 7, 9 };
var orderCustomerIds = new[] { 7, 7 };
var counts = customerIds.GroupJoin(
    orderCustomerIds, customerId => customerId, orderId => orderId,
    (customerId, orders) => $"{customerId}:{orders.Count()}");
Console.Write(string.Join(", ", counts));

var codes = new[] { "north", "NORTH", "south" };
var labels = codes.GroupBy(code => code, StringComparer.OrdinalIgnoreCase)
    .Select(group => $"{group.Key}:{group.Count()}");
Console.Write(string.Join(", ", labels));

var ids = new[] { 11, 12, 13, 14, 15 };
var sizes = ids.Chunk(2).Select(batch => batch.Length);
Console.Write(string.Join(",", sizes));

var labels = new[] { "A", "B", "C" };
var readings = new[] { 10, 20 };
var pairs = labels.Zip(readings, (label, reading) => $"{label}:{reading}");
Console.Write(string.Join(", ", pairs));

var draft = new[] { 4, 8, 6 };
var active = new[] { 4, 6, 8 };
Console.Write(draft.SequenceEqual(active));

var tickets = new[] { (Team: "Ops", Id: 21), (Team: "Ops", Id: 23) };
var byTeam = tickets.ToLookup(ticket => ticket.Team, ticket => ticket.Id);
Console.Write((byTeam["Ops"].Count(), byTeam["Sales"].Count()));

var rows = new[] { (Code: "R1", Quantity: 3), (Code: "r1", Quantity: 7) };
try
{
    var counts = rows.ToDictionary(row => row.Code, row => row.Quantity, StringComparer.OrdinalIgnoreCase);
    Console.Write(counts["R1"]);
}
catch (ArgumentException)
{
    Console.Write("duplicate");
}

int[] changes = [];
var balance = changes.Aggregate(50, (running, delta) => running + delta);
Console.Write(balance);

var packet = new[] { 0, 0, 7, 0, 4 };
var payload = packet.SkipWhile(value => value == 0);
Console.Write(string.Join(",", payload));

var contacts = new[] { (Id: 12, Address: "first"), (Id: 31, Address: "blocked"), (Id: 12, Address: "second"), (Id: 42, Address: "last") };
var blocked = new[] { 31 };
var recipients = contacts.ExceptBy(blocked, contact => contact.Id);
Console.Write(string.Join(",", recipients.Select(contact => contact.Address)));
